// Parse Google News RSS XML
const xml = $input.first().json.data;

// Extract titles from Google News RSS format
const titleMatches = xml.match(/<title>(.*?)<\/title>/g) || [];
const titles = titleMatches
  .map(t => t.replace(/<\/?title>/g, '').trim())
  .filter(t => 
    t && 
    t !== 'Google News' && 
    t.length > 10 &&
    !t.includes('Google News')
  )
  // Clean source names like " - TechCrunch" from titles
  .map(t => t.replace(/\s*-\s*[^-]+$/, '').trim());

// Niche keywords to prioritize
const nicheKeywords = [
  'ai', 'artificial intelligence', 'machine learning', 'chatgpt', 'openai',
  'gemini', 'llm', 'gpt', 'neural', 'deep learning',
  'tech', 'technology', 'software', 'apple', 'google', 'microsoft',
  'meta', 'nvidia', 'chip', 'semiconductor',
  'cyber', 'hack', 'security', 'breach', 'malware', 'ransomware', 'privacy',
  'science', 'research', 'space', 'nasa', 'quantum', 'robot',
  'bitcoin', 'crypto', 'blockchain', 'startup'
];

// Score and sort topics by niche relevance
const scoredTopics = titles.map(title => {
  const lower = title.toLowerCase();
  const score = nicheKeywords.filter(kw => lower.includes(kw)).length;
  return { title, score };
});

scoredTopics.sort((a, b) => b.score - a.score);

const nicheTopics = scoredTopics.map(t => t.title);
const selectedTopic = nicheTopics[0] || 'Latest Breakthroughs in Artificial Intelligence 2025';

console.log('Parsed titles:', titles.slice(0, 10));
console.log('Selected topic:', selectedTopic);

return [{ 
  json: { 
    selectedTopic, 
    allNicheTopics: nicheTopics.slice(0, 10),
    allTrends: titles.slice(0, 10)
  } 
}];

// Collect all data from previous nodes
const topic = $('🎯 Filter Niche Topics').item.json.selectedTopic;

// News articles
let newsArticles = [];
try {
  const newsData = $('📰 Fetch News Articles').item.json;
  if (newsData.articles && newsData.articles.length > 0) {
    newsArticles = newsData.articles.slice(0, 5).map(a => ({
      title: a.title || '',
      description: a.description || '',
      content: a.content || '',
      url: a.url || '',
      source: a.source?.name || ''
    }));
  }
} catch(e) { console.log('News fetch error:', e.message); }

// Wikipedia summary
let wikiSummary = '';
try {
  const wikiData = $('📚 Fetch Wikipedia Context').item.json;
  const searchResults = wikiData.query?.search;
  wikiSummary = searchResults && searchResults.length > 0 
  ? searchResults[0].snippet.replace(/<[^>]+>/g, '') 
  : '';
} catch(e) { console.log('Wiki fetch error:', e.message); }

// Unsplash images
let images = [];
try {
  const unsplashData = $('🖼️ Fetch Unsplash Images').item.json;
  if (unsplashData.results && unsplashData.results.length > 0) {
    images = unsplashData.results.map(img => ({
      url: img.urls?.regular || img.urls?.full || '',
      thumb: img.urls?.thumb || '',
      alt: img.alt_description || topic,
      photographer: img.user?.name || 'Unsplash',
      photographerUrl: img.user?.links?.html || 'https://unsplash.com'
    }));
  }
} catch(e) { console.log('Unsplash error:', e.message); }

// Use fallback image if none found
if (images.length === 0) {
  images = [{
    url: 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1200&h=630&fit=crop',
    alt: topic,
    photographer: 'Unsplash',
    photographerUrl: 'https://unsplash.com'
  }];
}

// Build news context string for the prompt
const newsContext = newsArticles.length > 0
  ? newsArticles.map((a, i) => `Article ${i+1}: ${a.title}\nSummary: ${a.description}\nSource: ${a.source}`).join('\n\n')
  : 'No recent news found. Use general knowledge about this topic.';

// Determine category
const topicLower = topic.toLowerCase();
let category = 'Tech';
if (topicLower.match(/ai|artificial intelligence|machine learning|llm|chatgpt|openai|gemini/)) category = 'AI';
else if (topicLower.match(/cyber|hack|security|breach|malware|privacy/)) category = 'Cyber';
else if (topicLower.match(/space|nasa|quantum|physics|biology|science|research/)) category = 'Science';
else if (topicLower.match(/bitcoin|crypto|blockchain/)) category = 'Tech';

// Generate slug
const slug = topic.toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 60);

// Today's date
const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    topic,
    slug,
    category,
    today,
    coverImage: images[0]?.url || '',
    images,
    newsContext,
    wikiSummary,
    newsArticles
  }
}];

// Extract the generated content from Basic LLM Chain output
let mdxContent = '';

try {
  mdxContent = $input.first().json.text || 
               $input.first().json.output || 
               $input.first().json.response || 
               JSON.stringify($input.first().json);
} catch(e) {
  throw new Error('Failed to extract content: ' + e.message);
}

// Clean up code fences
mdxContent = mdxContent
  .replace(/^```mdx\n/m, '')
  .replace(/^```md\n/m, '')
  .replace(/^```\n/m, '')
  .replace(/\n```$/m, '')
  .trim();

// Ensure it starts with frontmatter
if (!mdxContent.startsWith('---')) {
  const fmIndex = mdxContent.indexOf('---');
  if (fmIndex > -1) {
    mdxContent = mdxContent.substring(fmIndex);
  } else {
    throw new Error('No frontmatter found in generated content');
  }
}

// Fix tags - ensure it's always a proper YAML array
mdxContent = mdxContent.replace(
  /^tags:\s*(.+)$/m,
  (match, tagsValue) => {
    if (tagsValue.trim().startsWith('[')) return match;
    const tagList = tagsValue.split(',').map(t => `"${t.trim()}"`).join(', ');
    return `tags: [${tagList}]`;
  }
);

// Fix readTime - ensure it's a quoted string
mdxContent = mdxContent.replace(
  /^readTime:\s*(.+)$/m,
  (match, val) => {
    if (val.includes('"') || val.includes("'")) return match;
    return `readTime: "${val.trim()}"`;
  }
);

// Get values from Prepare Blog Data node
const slug = $('🔧 Prepare Blog Data').item.json.slug;
const today = $('🔧 Prepare Blog Data').item.json.today;
const topic = $('🔧 Prepare Blog Data').item.json.topic;

// Filename for GitHub
const filename = `${slug}.mdx`;

// Base64 encode safely for GitHub API
const base64Content = Buffer.from(mdxContent, 'utf-8').toString('base64');

console.log('MDX length:', mdxContent.length);
console.log('Filename:', filename);
console.log('Starts with:', mdxContent.substring(0, 100));

return [{
  json: {
    mdxContent,
    base64Content,
    filename,
    slug,
    today,
    topic,
    filePath: `content/posts/${filename}`
  }
}];

// Check if file already exists (to get SHA for update)
const checkResponse = $input.first().json;
const mdxData = $('📝 Extract & Process MDX').item.json;

let sha = null;
if (checkResponse.sha) {
  sha = checkResponse.sha;
  console.log('File exists, will update. SHA:', sha);
} else {
  console.log('File does not exist, will create new.');
}

return [{
  json: {
    ...mdxData,
    sha,
    fileExists: !!sha
  }
}];

// Final success log
const githubResponse = $input.first().json;
const topic = $('🔑 Get File SHA').item.json.topic;
const slug = $('🔑 Get File SHA').item.json.slug;
const today = $('🔑 Get File SHA').item.json.today;

const blogUrl = `https://pulseblogai.vercel.app/blog/${slug}`;
const commitUrl = githubResponse.commit?.html_url || 'https://github.com/Himanshu-Vishwakarma-GH/ai-tech-blog';

console.log('✅ Blog published successfully!');
console.log('Topic:', topic);
console.log('Blog URL:', blogUrl);
console.log('Commit:', commitUrl);

return [{
  json: {
    success: true,
    message: `✅ Blog published: "${topic}"`,
    blogUrl,
    commitUrl,
    publishedAt: new Date().toISOString(),
    topic,
    slug
  }
}];

